  const capturedAt = typeof record.capturedAt === "string" ? record.capturedAt : "";
  const processGroupId = Number(record.processGroupId);
  if (
    !Number.isSafeInteger(pid)
    || pid <= 0
    || !birthId
    || incarnation !== `${pid}:${birthId}`
    || !capturedAt
    || !Number.isFinite(Date.parse(capturedAt))
